/** The keyword transcoder's key table for a station, or undefined. */
export function keywordTableFor(osId: string): KeywordTable | undefined {
  return (KEYWORD_TABLES as Record<string, KeywordTable>)[osId];
}

/** Every station's table (the highlighter's keyword lists). */
export function keywordTables(): readonly KeywordTable[] {
  return Object.values(KEYWORD_TABLES);
}
